/**
 * Official product marks, inlined as data URLs so the Electron file:// build needs no asset-path resolution.
 * Sources (fetched from the products' own sites / their published favicon):
 *   zcode.z.ai, workbuddy.cn, codebuddy.cn, trae.ai, openclaw.ai, anthropic.com,
 *   opencode.ai, cursor.com, deepseek.com, factory.ai, groq.com, x.ai,
 *   plus Simple Icons brand marks (CC0 1.0) for the model-provider cards and
 *   the existing in-repo official marks (GrokBot, Hermes, Claude, Codex, pi).
 * Added cards use a brand-colour rounded tile with a white/dark mark so the icon
 * stays legible in both light and dark skins. Source SVGs/PNGs: public/engine-icons/.
 * A name match beats the driver mark: a bridged CLI (WorkBuddy/CodeBuddy) runs on the Claude
 * driver but is its own product, so it must not borrow Anthropic's star.
 */
export const ENGINE_BRAND_ICONS = {
  zcode: "data:image/png;base64,",
  workbuddy: "data:image/svg+xml;base64,",
  codebuddy: "data:image/svg+xml;base64,",
  trae: "data:image/png;base64,",
  openclaw: "data:image/svg+xml;base64,",
  claudeCode: "data:image/svg+xml;base64,",
  openai: "data:image/svg+xml;base64,",
  opencode: "data:image/png;base64,",
  cursor: "data:image/svg+xml;base64,",
  deepseek: "data:image/png;base64,",
  grok: "data:image/svg+xml;base64,",
  kimi: "data:image/png;base64,",
  doubao: "data:image/png;base64,",
  droid: "data:image/png;base64,",
  githubCopilot: "data:image/svg+xml;base64,",
  gemini: "data:image/svg+xml;base64,",
  xai: "data:image/png;base64,",
  mistral: "data:image/svg+xml;base64,",
  cerebras: "data:image/svg+xml;base64,",
  groq: "data:image/png;base64,",
  metaMuse: "data:image/svg+xml;base64,",
  museCode: "data:image/svg+xml;base64,",
  qwen: "data:image/svg+xml;base64,",
  hermes: "data:image/svg+xml;base64,",
  cline: "data:image/svg+xml;base64,",
  pi: "data:image/svg+xml;base64,",
  openrouter: "data:image/svg+xml;base64,",
  claudeApi: "data:image/svg+xml;base64,",
  minimax: "data:image/svg+xml;base64,",
  openaiCompat: "data:image/svg+xml;base64,",
} as const;

export type EngineBrand = keyof typeof ENGINE_BRAND_ICONS;

/** Order matters: compound names (WorkBuddy, CodeBuddy, OpenCode, OpenClaw) before their loose parts. */
const MATCHERS: ReadonlyArray<readonly [RegExp, EngineBrand]> = [
  [/workbuddy/i, "workbuddy"],
  [/codebuddy/i, "codebuddy"],
  [/^\s*z\s*-?code\b|\bzcode\b/i, "zcode"],
  [/claude\s*code/i, "claudeCode"],
  [/\bcodex\b|chatgpt|openai/i, "openai"],
  [/opencode/i, "opencode"],
  [/cursor/i, "cursor"],
  [/claw/i, "openclaw"],
  [/\btrae/i, "trae"],
  [/deepseek/i, "deepseek"],
  [/^\s*x\.?a\.?i\b|\bxai\b/i, "xai"],
  [/\bgrok\b/i, "grok"],
  [/\bkimi\b|moonshot/i, "kimi"],
  [/doubao|豆包/i, "doubao"],
  [/\bdroid\b|factory/i, "droid"],
  [/copilot/i, "githubCopilot"],
  [/gemini|antigravity/i, "gemini"],
  [/mistral/i, "mistral"],
  [/cerebras/i, "cerebras"],
  [/\bgroq\b/i, "groq"],
  [/muse\s*code/i, "museCode"],
  [/meta muse|meta ai|\bmeta\b/i, "metaMuse"],
  [/\bqwen\b/i, "qwen"],
  [/\bhermes\b/i, "hermes"],
  [/\bcline\b/i, "cline"],
  [/\bpi(?:\.dev)?\b/i, "pi"],
  [/openrouter/i, "openrouter"],
  [/claude \(api key\)/i, "claudeApi"],
  [/openai.?compatible/i, "openaiCompat"],
  [/minimax/i, "minimax"],
];

/** The official mark for a display name, or null to fall through to the driver mark. */
export function engineBrandIcon(name: string | null | undefined): string | null {
  if (!name) return null;
  for (const [pattern, brand] of MATCHERS) if (pattern.test(name)) return ENGINE_BRAND_ICONS[brand];
  return null;
}

/** Some built-in instances store no displayName; the driver kind still identifies the product. */
const DRIVER_BRANDS: Readonly<Record<string, EngineBrand>> = {
  // Only drivers whose ProviderMark fell through to a bare first letter belong here.
  // Drivers with an existing in-repo official SVG mark keep it (and an explicit
  // user-chosen icon preset still wins before this fallback is reached).
  cerebras: "cerebras", groq: "groq", clineAgent: "cline",
  geminiAgent: "gemini", minimax: "minimax", "openai-compat": "openai",
  customAcp: "openaiCompat",
};

/** Official mark for a driver kind, or null when the existing driver mark should win. */
export function engineBrandIconForDriver(driverKind: string | null | undefined): string | null {
  if (!driverKind) return null;
  const brand = DRIVER_BRANDS[driverKind];
  return brand ? ENGINE_BRAND_ICONS[brand] : null;
}
